# Slot 1 → osc.fm  (expressive pitch vibrato)
# `src` binds another module's output to a clean name — here the amp envelope,
# so the vibrato tapers away as the note releases. The vibrato eases in over
# ~1 s (smoothstep on `age`), its depth follows the mod wheel, and each note
# picks its own random speed (rand() is latched per note-on) so no two notes
# wobble identically. Remember: YAMS is eager — phasor() keeps ticking every
# block regardless of the envelope value, so the LFO never stalls or jumps.
src eg = env-1.out

let fade = smoothstep(0.2, 1.2, age)
let depth = lerp(0.04, 0.14, mod_wheel)
let rate = lerp(4.5, 6.5, rand())
let vib = sin(phasor(rate) * tau)
out = vib * depth * fade * eg
